/**
 * Definition for singly-linked list.
 * public class ListNode {
 *     int val;
 *     ListNode next;
 *     ListNode() {}
 *     ListNode(int val) { this.val = val; }
 *     ListNode(int val, ListNode next) { this.val = val; this.next = next; }
 * }
 */
class Solution {
    public ListNode reverseKGroup(ListNode head, int k) {
        ListNode dummy = new ListNode(-1);
        dummy.next = head;
        ListNode pre = dummy;
        ListNode next;
        ListNode start = head;
        ListNode end = dummy;
        while(end!=null){
            for(int i = 0;i<k && end!=null;i++){
                end = end.next;
            }
            if(end==null)
            break;
            start = pre.next;
            next = end.next;
            end.next = null;
            end = reverseList(start);
            pre.next = end;
            start.next = next;
            pre = start;
            end = start;
        }
        return dummy.next;
    }
    public ListNode reverseList(ListNode head){
        ListNode cur = head;
        ListNode pre = null;
        while(cur!=null){
            ListNode temp = cur.next;
            cur.next = pre;
            pre = cur;
            cur = temp;
        }
        return pre;
    }
}
